import json
import re
import sqlite3
import subprocess
from contextlib import closing
from langchain_core.tools import tool
DB_PATH = '/var/lib/homehub/climate.db'
CLIMATECTL_BIN = '/usr/local/bin/homehub-climatectl'
_DAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'}
_TIME_RE = re.compile('^([01]\\d|2[0-3]):[0-5]\\d$')

def _load_schedule(conn, thermostat_id):
    row = conn.execute('SELECT schedule_json FROM thermostat_schedules WHERE thermostat_id = ?', (thermostat_id,)).fetchone()
    if row is None:
        return None
    return json.loads(row[0])

def _push_schedule_to_device(thermostat_id):
    # Ask the hub's climate controller CLI to sync the stored schedule to the physical device.
    try:
        result = subprocess.run([CLIMATECTL_BIN, 'push-schedule', '--thermostat', thermostat_id], capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {'ok': False, 'error': str(exc)}
    return {'ok': result.returncode == 0, 'output': result.stdout.strip() or result.stderr.strip()}

@tool
def update_thermostat_schedule(thermostat_id: str, day: str, start_time: str, target_celsius: float) -> dict:
    day = day.strip().lower()
    if day not in _DAYS:
        return {'ok': False, 'error': f"unknown day '{day}'"}
    if not _TIME_RE.match(start_time):
        return {'ok': False, 'error': 'start_time must be HH:MM'}
    if not 5 <= target_celsius <= 30:
        return {'ok': False, 'error': 'target_celsius must be between 5 and 30'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            schedule = _load_schedule(conn, thermostat_id)
            if schedule is None:
                return {'ok': False, 'error': f"no schedule for thermostat '{thermostat_id}'"}
            slots = schedule.setdefault(day, [])
            previous = None
            for slot in slots:
                if slot['start'] == start_time:
                    previous = slot['target_c']
                    slot['target_c'] = round(target_celsius, 1)
                    break
            else:
                slots.append({'start': start_time, 'target_c': round(target_celsius, 1)})
                slots.sort(key=lambda s: s['start'])
            conn.execute('UPDATE thermostat_schedules SET schedule_json = ?, updated_at = CURRENT_TIMESTAMP WHERE thermostat_id = ?', (json.dumps(schedule), thermostat_id))
    device_sync = _push_schedule_to_device(thermostat_id)
    return {'ok': True, 'thermostat_id': thermostat_id, 'day': day, 'start_time': start_time, 'previous_target_c': previous, 'new_target_c': round(target_celsius, 1), 'slots_for_day': slots, 'device_sync': device_sync}
